function validate([d, low, high]) {
  if (!Number.isInteger(d) || d < 0 || d > 9) return 'd is a single digit from 0 to 9.';
  if (!Number.isInteger(low) || !Number.isInteger(high)) return 'low and high must be integers.';
  if (low < 1 || high > 200000000) return 'low and high are between 1 and 200000000.';
  if (low > high) return 'low cannot be larger than high.';
  return null;
}

