function digitsCount(d, low, high) {
  const countUpTo = (n) => {
    const digits = String(n);
    const memo = new Map();
    const dfs = (pos, count, tight, started) => {
      if (pos === digits.length) return count;
      const key = `${pos},${count},${tight},${started}`;
      if (memo.has(key)) return memo.get(key);
      const limit = tight ? Number(digits[pos]) : 9;
      let total = 0;
      for (let digit = 0; digit <= limit; digit++) {
        const nowStarted = started || digit > 0;
        const hit = nowStarted && digit === d ? 1 : 0;
        total += dfs(pos + 1, count + hit, tight && digit === limit, nowStarted);
      }
      memo.set(key, total);
      return total;
    };
    return dfs(0, 0, true, false);
  };
  return countUpTo(high) - countUpTo(low - 1);
}

