function generate(rand, size) {
  const d = Math.floor(rand() * 10);
  if (size === 'large') {
    const high = 1 + Math.floor(rand() * 200000000);
    const low = 1 + Math.floor(rand() * Math.min(high, 1000 + Math.floor(rand() * high)));
    return [d, low, high];
  }
  // Small ranges, sometimes placed right around a power of ten.
  const power = [1, 10, 100, 1000, 10000, 100000][Math.floor(rand() * 6)];
  const around = rand() < 0.4;
  const low = around ? Math.max(1, power - Math.floor(rand() * 30)) : 1 + Math.floor(rand() * 3000);
  const high = low + Math.floor(rand() * (around ? 60 : 400));
  return [d, low, high];
}
